//! Two-factor authentication by authenticator app (TOTP, RFC 6238: HMAC-SHA1, 6 digits, 30 seconds) and its
//! recovery codes, for the `totp*` and `recovery*` steps.
//!
//! The secret has to be readable again to check a code, so it is encrypted at rest, never hashed. What the
//! steps keep in the database is in two tables of their own, created with the schema of the service:
//! the last time step accepted for an account (the anti-replay), and the hashes of its recovery codes.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{Result, anyhow};
use hmac::{Hmac, KeyInit, Mac};
use sha1::Sha1;

use crate::crypto;
use crate::http::HttpError;

/// The last time step accepted for each account: a code is only taken for a step newer than it.
pub const CREATE_STEPS_TABLE: &str =
    "CREATE TABLE IF NOT EXISTS totp_steps (account TEXT PRIMARY KEY, last_step BIGINT NOT NULL)";

/// The recovery codes of each account, by hash. `used_at` is set when one is spent.
pub const CREATE_RECOVERY_TABLE: &str = "CREATE TABLE IF NOT EXISTS recovery_codes (account TEXT NOT NULL, code_hash TEXT NOT NULL, used_at TIMESTAMPTZ, PRIMARY KEY (account, code_hash))";

const STEP_SECS: u64 = 30;
const DIGITS: u32 = 6;
/// Steps on each side of the current one that are still accepted: a clock that drifts by up to 30 seconds.
const SKEW: u64 = 1;
const SECRET_LEN: usize = 20;
/// 10 characters of 5 bits.
const RECOVERY_LEN: usize = 10;
const ALPHABET: &[u8; 32] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

type HmacSha1 = Hmac<Sha1>;

/// What a new enrolment hands over.
pub struct Setup {
    /// The secret, sealed, to store.
    pub sealed: String,
    /// `otpauth://` URI: the client draws the QR code from it.
    pub otpauth_url: String,
    /// The secret in base32, to type by hand. Never stored.
    pub secret: String,
}

/// The step `totpGenerate`.
pub fn generate(key_env: &str, issuer: &str, account: &str) -> Result<Setup> {
    let mut secret = [0u8; SECRET_LEN];
    rand::fill(&mut secret);
    let base32 = base32(&secret);
    let (issuer, account) = (percent(issuer), percent(account));
    Ok(Setup {
        sealed: crypto::encrypt(key_env, &hex::encode(secret))?,
        otpauth_url: format!(
            "otpauth://totp/{issuer}:{account}?secret={base32}&issuer={issuer}&algorithm=SHA1&digits={DIGITS}&period={STEP_SECS}"
        ),
        secret: base32,
    })
}

/// The step `totpVerify`: the code must match the secret within the window, and be for a step newer than the last one
/// accepted for `account`. Anything else is the same 401. Call it in the transaction of the handler.
pub async fn verify(
    tx: &mut sqlx::PgConnection,
    key_env: &str,
    sealed: &str,
    code: &str,
    account: &str,
) -> Result<()> {
    verify_at(tx, key_env, sealed, code, account, unix_now()).await
}

async fn verify_at(
    tx: &mut sqlx::PgConnection,
    key_env: &str,
    sealed: &str,
    code: &str,
    account: &str,
    now: u64,
) -> Result<()> {
    // No secret stored: the account has not enrolled, which is not a reason to tell a stranger apart.
    if sealed.trim().is_empty() {
        return Err(invalid());
    }
    let secret = hex::decode(crypto::decrypt(key_env, sealed)?)
        .map_err(|_| anyhow!("a stored TOTP secret is not hexadecimal"))?;
    let Some(step) = matching_step(&secret, code, now) else {
        return Err(invalid());
    };
    if accept(tx, account, step).await? {
        Ok(())
    } else {
        tracing::warn!("a TOTP code was used twice");
        Err(invalid())
    }
}

/// Records `step` as the last one accepted for `account`, if it is newer than the one before. One statement:
/// two requests racing with the same code cannot both win, the second waits for the first to commit and then
/// finds the step taken.
async fn accept(tx: &mut sqlx::PgConnection, account: &str, step: u64) -> Result<bool> {
    let changed = sqlx::query(
        "INSERT INTO totp_steps (account, last_step) VALUES ($1, $2) \
         ON CONFLICT (account) DO UPDATE SET last_step = EXCLUDED.last_step \
         WHERE totp_steps.last_step < EXCLUDED.last_step",
    )
    .bind(account)
    .bind(step as i64)
    .execute(tx)
    .await?
    .rows_affected();
    Ok(changed == 1)
}

/// The step `recoveryCodes`: `count` new codes (`XXXXX-XXXXX`) for `account`, and the ones it had are gone. Only their
/// hashes are stored.
pub async fn issue_recovery_codes(
    tx: &mut sqlx::PgConnection,
    account: &str,
    count: u32,
) -> Result<Vec<String>> {
    sqlx::query("DELETE FROM recovery_codes WHERE account = $1")
        .bind(account)
        .execute(&mut *tx)
        .await?;
    let mut shown = Vec::new();
    for _ in 0..count {
        let mut random = [0u8; RECOVERY_LEN];
        rand::fill(&mut random);
        let code: String = random.iter().map(|b| ALPHABET[(b & 31) as usize] as char).collect();
        // Two codes the same, by chance in 2^50: the primary key refuses the second, which is skipped.
        let stored = sqlx::query(
            "INSERT INTO recovery_codes (account, code_hash) VALUES ($1, $2) ON CONFLICT DO NOTHING",
        )
        .bind(account)
        .bind(recovery_hash(account, &code))
        .execute(&mut *tx)
        .await?
        .rows_affected();
        if stored == 1 {
            shown.push(format!("{}-{}", &code[..RECOVERY_LEN / 2], &code[RECOVERY_LEN / 2..]));
        }
    }
    Ok(shown)
}

/// The step `recoveryCodeUse`: spends a code of `account`. One statement, so a code works once even when two
/// requests present it together.
pub async fn use_recovery_code(tx: &mut sqlx::PgConnection, account: &str, code: &str) -> Result<()> {
    let spent = sqlx::query(
        "UPDATE recovery_codes SET used_at = now() \
         WHERE account = $1 AND code_hash = $2 AND used_at IS NULL",
    )
    .bind(account)
    .bind(recovery_hash(account, &normalize(code)))
    .execute(tx)
    .await?
    .rows_affected();
    if spent == 1 { Ok(()) } else { Err(invalid()) }
}

fn invalid() -> anyhow::Error {
    HttpError::unauthorized("invalid code").into()
}

/// What is stored of a code: salted with the account, so that equal codes of two accounts differ. A code has 50
/// bits, which only the limit on attempts protects online; a leaked table is not meant to be a secret for long.
fn recovery_hash(account: &str, canonical: &str) -> String {
    crypto::sha256_hex(&format!("{account}:{canonical}"))
}

/// A code as typed: any case, with or without dash or spaces.
fn normalize(input: &str) -> String {
    input
        .chars()
        .filter(char::is_ascii_alphanumeric)
        .collect::<String>()
        .to_ascii_uppercase()
}

fn unix_now() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map_or(0, |d| d.as_secs())
}

/// The code of the HOTP counter `counter` (RFC 4226).
fn hotp(secret: &[u8], counter: u64) -> String {
    let mut mac = HmacSha1::new_from_slice(secret).expect("HMAC takes a key of any length");
    mac.update(&counter.to_be_bytes());
    let digest = mac.finalize().into_bytes();
    let offset = (digest[19] & 0x0f) as usize;
    let value = u32::from_be_bytes([digest[offset] & 0x7f, digest[offset + 1], digest[offset + 2], digest[offset + 3]]);
    format!("{:0width$}", value % 10u32.pow(DIGITS), width = DIGITS as usize)
}

/// The time step that `code` belongs to within the window around `now`, the latest if several match. Every step of
/// the window is compared, in constant time, whether or not an earlier one matched.
fn matching_step(secret: &[u8], code: &str, now: u64) -> Option<u64> {
    let code: Vec<u8> = code.bytes().filter(|b| !b.is_ascii_whitespace()).collect();
    let current = now / STEP_SECS;
    let mut matched = None;
    for step in current.saturating_sub(SKEW)..=current + SKEW {
        if constant_time_eq(hotp(secret, step).as_bytes(), &code) {
            matched = Some(step);
        }
    }
    matched
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    a.len() == b.len() && a.iter().zip(b).fold(0u8, |diff, (x, y)| diff | (x ^ y)) == 0
}

/// RFC 4648 base32, without padding: what authenticator apps take as a secret.
fn base32(bytes: &[u8]) -> String {
    let mut out = String::new();
    let (mut buffer, mut bits) = (0u32, 0);
    for &byte in bytes {
        buffer = (buffer << 8) | u32::from(byte);
        bits += 8;
        while bits >= 5 {
            out.push(ALPHABET[((buffer >> (bits - 5)) & 31) as usize] as char);
            bits -= 5;
        }
    }
    if bits > 0 {
        out.push(ALPHABET[((buffer << (5 - bits)) & 31) as usize] as char);
    }
    out
}

/// A part of a URI: everything but the unreserved characters is percent-encoded.
fn percent(text: &str) -> String {
    let mut out = String::new();
    for b in text.bytes() {
        if b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~') {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The key of the RFC 6238 appendix B (SHA-1).
    const RFC_SECRET: &[u8] = b"12345678901234567890";

    #[test]
    fn the_codes_of_the_rfc_are_reproduced() {
        // The RFC lists 8 digits; the last 6 are what this service uses.
        for (time, code) in [
            (59u64, "287082"),
            (1_111_111_109, "081804"),
            (1_111_111_111, "050471"),
            (1_234_567_890, "005924"),
            (2_000_000_000, "279037"),
            (20_000_000_000, "353130"),
        ] {
            assert_eq!(hotp(RFC_SECRET, time / STEP_SECS), code, "{time}");
        }
    }

    #[test]
    fn a_secret_is_written_in_base32_as_authenticator_apps_read_it() {
        assert_eq!(base32(RFC_SECRET), "GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ");
        assert_eq!(base32(b"f"), "MY");
        assert_eq!(base32(b"foobar"), "MZXW6YTBOI");
        assert_eq!(base32(b""), "");
    }

    #[test]
    fn the_window_is_one_step_each_side_and_no_more() {
        let now = 1_700_000_000u64;
        let current = now / STEP_SECS;
        for offset in [-1i64, 0, 1] {
            let step = (current as i64 + offset) as u64;
            assert_eq!(matching_step(RFC_SECRET, &hotp(RFC_SECRET, step), now), Some(step), "{offset}");
        }
        for offset in [-3i64, -2, 2, 3] {
            let step = (current as i64 + offset) as u64;
            let code = hotp(RFC_SECRET, step);
            // The code of a far step can equal one of the window by chance (1 in 10^6): skip that.
            if (current - 1..=current + 1).all(|s| hotp(RFC_SECRET, s) != code) {
                assert_eq!(matching_step(RFC_SECRET, &code, now), None, "{offset}");
            }
        }
    }

    #[test]
    fn a_code_as_typed_is_read_forgivingly_but_never_loosely() {
        let now = 1_700_000_000u64;
        let code = hotp(RFC_SECRET, now / STEP_SECS);
        let spaced = format!("{} {}", &code[..3], &code[3..]);
        assert!(matching_step(RFC_SECRET, &spaced, now).is_some());
        assert!(matching_step(RFC_SECRET, &format!(" {code}\n"), now).is_some());
        for wrong in ["", "000", "12345678", "abcdef", &format!("{code}0"), &code[1..]] {
            assert_eq!(matching_step(RFC_SECRET, wrong, now), None, "{wrong:?}");
        }
    }

    #[test]
    fn the_uri_names_the_issuer_and_the_account_once_encoded() {
        // The key comes from the environment: any 32 bytes in hexadecimal.
        unsafe { std::env::set_var("TOTP_TEST_KEY", "11".repeat(32)) };
        let setup = generate("TOTP_TEST_KEY", "Acme & Co", "jean+test@dupont.fr").unwrap();
        assert!(
            setup.otpauth_url.starts_with("otpauth://totp/Acme%20%26%20Co:jean%2Btest%40dupont.fr?secret="),
            "{}",
            setup.otpauth_url
        );
        assert!(setup.otpauth_url.contains(&format!("secret={}", setup.secret)));
        assert!(setup.otpauth_url.ends_with("&issuer=Acme%20%26%20Co&algorithm=SHA1&digits=6&period=30"));
        // 20 bytes make 32 base32 characters, and what is stored is neither the secret nor its text.
        assert_eq!(setup.secret.len(), 32);
        assert!(!setup.sealed.contains(&setup.secret));
        // What is stored opens, with the key, to the secret the URI carries.
        let secret = hex::decode(crypto::decrypt("TOTP_TEST_KEY", &setup.sealed).unwrap()).unwrap();
        assert_eq!(base32(&secret), setup.secret);
        // Two enrolments never share a secret.
        assert_ne!(generate("TOTP_TEST_KEY", "a", "b").unwrap().secret, setup.secret);
    }

    #[test]
    fn recovery_codes_are_typed_in_any_form() {
        assert_eq!(normalize("abcde-23456"), "ABCDE23456");
        assert_eq!(normalize(" abcde 23456\n"), "ABCDE23456");
        // Salted by account.
        assert_ne!(recovery_hash("a", "ABCDE23456"), recovery_hash("b", "ABCDE23456"));
        assert_eq!(recovery_hash("a", "ABCDE23456").len(), 64);
    }

    mod database {
        use super::*;
        use sqlx::PgPool;

        static TABLES: tokio::sync::OnceCell<()> = tokio::sync::OnceCell::const_new();

        /// Needs a database: `EDA_TEST_DATABASE_URL=postgres://... cargo test -p eda-runtime -- --ignored`. Each test
        /// works on accounts of its own, so that they can run side by side.
        async fn database() -> PgPool {
            let url = std::env::var("EDA_TEST_DATABASE_URL").expect("EDA_TEST_DATABASE_URL");
            let db = PgPool::connect(&url).await.unwrap();
            TABLES
                .get_or_init(|| async {
                    sqlx::query(CREATE_STEPS_TABLE).execute(&db).await.unwrap();
                    sqlx::query(CREATE_RECOVERY_TABLE).execute(&db).await.unwrap();
                })
                .await;
            db
        }

        fn is_invalid(result: Result<()>) -> bool {
            result.err().and_then(|e| e.downcast::<HttpError>().ok()).is_some_and(|e| e.status == 401 && e.message == "invalid code")
        }

        #[tokio::test]
        #[ignore = "needs EDA_TEST_DATABASE_URL"]
        async fn a_code_is_accepted_once_and_a_later_one_still_passes() {
            unsafe { std::env::set_var("TOTP_TEST_KEY", "11".repeat(32)) };
            let db = database().await;
            let account = "totp-replay";
            sqlx::query("DELETE FROM totp_steps WHERE account = $1").bind(account).execute(&db).await.unwrap();
            let setup = generate("TOTP_TEST_KEY", "Acme", "a@b.fr").unwrap();
            let secret = hex::decode(crypto::decrypt("TOTP_TEST_KEY", &setup.sealed).unwrap()).unwrap();
            let now = 1_700_000_000u64;
            let code_at = |step: u64| hotp(&secret, step);
            let current = now / STEP_SECS;

            let mut tx = db.begin().await.unwrap();
            verify_at(&mut tx, "TOTP_TEST_KEY", &setup.sealed, &code_at(current), account, now).await.unwrap();
            // The same code again, and the code of the step before: both are behind.
            assert!(is_invalid(verify_at(&mut tx, "TOTP_TEST_KEY", &setup.sealed, &code_at(current), account, now).await));
            assert!(is_invalid(verify_at(&mut tx, "TOTP_TEST_KEY", &setup.sealed, &code_at(current - 1), account, now).await));
            // The next step passes.
            verify_at(&mut tx, "TOTP_TEST_KEY", &setup.sealed, &code_at(current + 1), account, now).await.unwrap();
            tx.commit().await.unwrap();

            // Another account has its own history; a wrong code and an account that never enrolled are refused alike.
            let mut tx = db.begin().await.unwrap();
            verify_at(&mut tx, "TOTP_TEST_KEY", &setup.sealed, &code_at(current), "totp-replay-other", now).await.unwrap();
            assert!(is_invalid(verify_at(&mut tx, "TOTP_TEST_KEY", &setup.sealed, "000000", "totp-replay-third", now).await));
            assert!(is_invalid(verify_at(&mut tx, "TOTP_TEST_KEY", "", "123456", "totp-replay-third", now).await));
        }

        #[tokio::test]
        #[ignore = "needs EDA_TEST_DATABASE_URL"]
        async fn two_requests_with_the_same_code_cannot_both_pass() {
            unsafe { std::env::set_var("TOTP_TEST_KEY", "11".repeat(32)) };
            let db = database().await;
            let account = "totp-race";
            sqlx::query("DELETE FROM totp_steps WHERE account = $1").bind(account).execute(&db).await.unwrap();
            let setup = generate("TOTP_TEST_KEY", "Acme", "a@b.fr").unwrap();
            let secret = hex::decode(crypto::decrypt("TOTP_TEST_KEY", &setup.sealed).unwrap()).unwrap();
            let now = 1_700_000_000u64;
            let code = hotp(&secret, now / STEP_SECS);
            let attempts = (0..8).map(|_| {
                let (db, sealed, code) = (db.clone(), setup.sealed.clone(), code.clone());
                tokio::spawn(async move {
                    let mut tx = db.begin().await.unwrap();
                    let result = verify_at(&mut tx, "TOTP_TEST_KEY", &sealed, &code, account, now).await;
                    tx.commit().await.unwrap();
                    result.is_ok()
                })
            });
            let mut accepted = 0;
            for attempt in attempts.collect::<Vec<_>>() {
                accepted += usize::from(attempt.await.unwrap());
            }
            assert_eq!(accepted, 1);
        }

        #[tokio::test]
        #[ignore = "needs EDA_TEST_DATABASE_URL"]
        async fn a_recovery_code_works_once_and_new_ones_replace_the_old() {
            let db = database().await;
            let account = "recovery-once";
            let mut tx = db.begin().await.unwrap();
            let codes = issue_recovery_codes(&mut tx, account, 8).await.unwrap();
            tx.commit().await.unwrap();
            assert_eq!(codes.len(), 8);
            assert!(codes.iter().all(|c| c.len() == 11 && c.as_bytes()[5] == b'-'), "{codes:?}");

            let mut tx = db.begin().await.unwrap();
            // Typed in lower case, without the dash.
            use_recovery_code(&mut tx, account, &codes[0].replace('-', "").to_lowercase()).await.unwrap();
            assert!(is_invalid(use_recovery_code(&mut tx, account, &codes[0]).await));
            // Another account's code is no use here, and nor is a guess.
            assert!(is_invalid(use_recovery_code(&mut tx, "recovery-other", &codes[1]).await));
            assert!(is_invalid(use_recovery_code(&mut tx, account, "AAAAA-AAAAA").await));
            use_recovery_code(&mut tx, account, &codes[1]).await.unwrap();
            tx.commit().await.unwrap();

            // Issuing again forgets the old ones, spent or not.
            let mut tx = db.begin().await.unwrap();
            let fresh = issue_recovery_codes(&mut tx, account, 3).await.unwrap();
            assert_eq!(fresh.len(), 3);
            assert!(is_invalid(use_recovery_code(&mut tx, account, &codes[2]).await));
            use_recovery_code(&mut tx, account, &fresh[0]).await.unwrap();
            tx.commit().await.unwrap();
        }
    }
}
